package com.bank.sequence.gen;

import java.util.logging.Logger;

// Standalone sequence with a per-session cache (block allocation causes gaps).
public class Sequence {
    private static final Logger log = Logger.getLogger(Sequence.class.getName());
    private long global = 0;          // authoritative counter
    private final int cacheSize;
    private long cacheStart = 0, cacheEnd = 0, cursor = 0;

    public Sequence(int cacheSize) { this.cacheSize = cacheSize; }

    // nextval: hand out from the cached block, refilling the block when exhausted.
    public synchronized long nextval() {
        if (cursor >= cacheEnd) {           // refill: grab a block of cacheSize
            cacheStart = global + 1;
            global += cacheSize;
            cacheEnd = global;
            cursor = cacheStart;
            final long cs = cacheStart, ce = cacheEnd;
            log.fine(() -> "cached block [" + cs + ".." + ce + "]");
        }
        return cursor++;
    }

    // Session ends: unused cached values are discarded → a gap.
    public synchronized void endSession() {
        if (cursor <= cacheEnd) {
            final long from = cursor, to = cacheEnd;
            log.warning(() -> "session end → discarding cached values " + from + ".." + to + " (GAP)");
            cursor = cacheEnd + 1;
        }
    }
}
