package com.bank.sequence.service;

import com.bank.sequence.gen.Sequence;
import java.util.logging.Logger;

public class ReferenceService {
    private static final Logger log = Logger.getLogger(ReferenceService.class.getName());
    private final Sequence shared;

    public ReferenceService(Sequence shared) { this.shared = shared; }

    public long newTransferRef() {
        long ref = shared.nextval();
        log.info(() -> "transfer ref_no=" + ref);
        return ref;
    }
    public long newLoanRef() {
        long ref = shared.nextval();
        log.info(() -> "loan ref_no=" + ref + " (same pool as transfers)");
        return ref;
    }
    // A drawn value that is rolled back is never returned → gap.
    public void rolledBackDraw() {
        long wasted = shared.nextval();
        log.warning(() -> "drew ref_no=" + wasted + " then ROLLBACK → value lost (GAP)");
    }
}
