package com.bank.sequence;

import com.bank.sequence.gen.*;
import com.bank.sequence.service.ReferenceService;
import java.util.logging.*;

public class SequenceDemo {
    private static final Logger log = Logger.getLogger(SequenceDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        Sequence shared = new Sequence(50);
        ReferenceService refs = new ReferenceService(shared);

        log.info("=== Shared sequence across two tables ===");
        refs.newTransferRef();   // 1
        refs.newLoanRef();       // 2  (same pool!)
        refs.newTransferRef();   // 3

        log.info("=== Rollback causes a gap ===");
        refs.rolledBackDraw();   // 4 wasted
        refs.newTransferRef();   // 5 (4 is missing)

        log.info("=== Table-bound identity is separate ===");
        TableIdentity auditIds = new TableIdentity();
        log.info("audit_log id=" + auditIds.nextForThisTableOnly() + " (independent of ref_seq)");

        log.info("=== Caching gap at session end ===");
        shared.endSession();     // discards cached 6..50
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

